// ⚙️ CONFIG: App ID do bot (Developer Portal → Bot management)
const BOT_APP_ID = 'COLE_AQUI_O_APP_ID_DO_BOT';

const a = $input.first().json.body || {};
const EXT_AUDIO = ['mp3','m4a','wav','webm','ogg','oga','mp4','mpeg','mpga','flac','aac','opus'];

let rota = 'outro';

// Segurança mínima: a activity tem que ser para o seu bot e vir de um serviceUrl do Teams.
// (O token do bot é enviado para o serviceUrl, então NUNCA aceite um serviceUrl qualquer.)
const paraMeuBot = (a.recipient?.id || '').endsWith(BOT_APP_ID);
const serviceUrlOk = /^https:\/\/smba\.trafficmanager\.net\//i.test(a.serviceUrl || '');

const arquivo = (a.attachments || []).find(
  x => x.contentType === 'application/vnd.microsoft.teams.file.download.info'
);
const ehAudio = !!arquivo && EXT_AUDIO.includes((arquivo.content?.fileType || '').toLowerCase());

if (paraMeuBot && serviceUrlOk) {
  if (a.type === 'invoke' && a.name === 'task/fetch') rota = 'taskfetch';
  else if (a.type === 'message' && ehAudio) rota = 'audio';
  else if (a.type === 'message') rota = 'texto';
}

return [{ json: { rota, activity: a, arquivo: arquivo || null, arquivoNaoAudio: !!arquivo && !ehAudio } }];

// ⚙️ CONFIG: URL pública (HTTPS) onde você hospedou o gravar.html
const PAGINA_GRAVADOR = 'https://SEU-DOMINIO/gravar.html';

const a = $input.first().json.activity;
const store = $getWorkflowStaticData('global');
store.sessoes = store.sessoes || {};

// limpa sessões vencidas
const agora = Date.now();
for (const [k, v] of Object.entries(store.sessoes)) if (v.expira < agora) delete store.sessoes[k];

// token de uso único: a página manda ele de volta junto com o áudio
let token;
try { token = require('crypto').randomBytes(24).toString('hex'); }
catch (e) { token = Array.from({ length: 48 }, () => Math.floor(Math.random() * 16).toString(16)).join(''); }

store.sessoes[token] = {
  conversationId: a.conversation.id,
  serviceUrl: a.serviceUrl,
  expira: agora + 10 * 60 * 1000, // 10 minutos
};

return [{ json: { resposta: { task: { type: 'continue', value: {
  title: 'Gravar áudio',
  url: `${PAGINA_GRAVADOR}?s=${token}`,
  height: 320,
  width: 420,
} } } } }];

const { activity: a, arquivo } = $input.first().json;
return [{ json: {
  serviceUrl: a.serviceUrl,
  conversationId: a.conversation.id,
  downloadUrl: arquivo.content.downloadUrl,
  nome: arquivo.name,
} }];

const { activity: a, arquivoNaoAudio } = $input.first().json;

const card = {
  type: 'AdaptiveCard',
  $schema: 'http://adaptivecards.io/schemas/adaptive-card.json',
  version: '1.4',
  body: [
    { type: 'TextBlock', weight: 'Bolder', size: 'Medium',
      text: arquivoNaoAudio ? 'Esse arquivo não parece ser um áudio 🤔' : 'Oi! Me manda um áudio 🎙️' },
    { type: 'TextBlock', wrap: true,
      text: 'Você pode anexar um arquivo de áudio aqui no chat ou gravar agora pelo botão abaixo.' },
  ],
  actions: [
    { type: 'Action.Submit', title: '🎙️ Gravar áudio', data: { msteams: { type: 'task/fetch' } } },
  ],
};

return [{ json: {
  serviceUrl: a.serviceUrl,
  conversationId: a.conversation.id,
  activity: { type: 'message', attachments: [{ contentType: 'application/vnd.microsoft.card.adaptive', content: card }] },
} }];

// Confere o token de uso único criado no clique do botão
const item = $input.first();
const s = item.json.body?.s || item.json.query?.s;
const store = $getWorkflowStaticData('global');
const sessao = store.sessoes?.[s];

if (!sessao || sessao.expira < Date.now()) throw new Error('Sessão inválida ou expirada');
delete store.sessoes[s]; // uso único

return [{ json: { serviceUrl: sessao.serviceUrl, conversationId: sessao.conversationId }, binary: item.binary || {} }];

// Ponto de encontro dos dois caminhos (arquivo no chat e gravador).
// Sai daqui sempre: json { serviceUrl, conversationId } + binary.audio
const item = $input.first();
let ctx = item.json;
if (!ctx.serviceUrl) ctx = $('Preparar download').first().json;

const bin = item.binary || {};
const chave = Object.keys(bin)[0];
if (!chave) throw new Error('Nenhum áudio recebido');

const audio = bin[chave];
if (ctx.nome) audio.fileName = ctx.nome; // a OpenAI usa a extensão do nome para saber o formato

return [{ json: { serviceUrl: ctx.serviceUrl, conversationId: ctx.conversationId }, binary: { audio } }];

// 👉 Aqui é onde você pluga o resto da sua automação (resumo, salvar no banco, etc.)
const ctx = $('Contexto do áudio').first().json;
const texto = ($input.first().json.text || '').trim() || '(não consegui entender o áudio)';

return [{ json: {
  serviceUrl: ctx.serviceUrl,
  conversationId: ctx.conversationId,
  activity: { type: 'message', text: `📝 **Transcrição:**\n\n${texto}` },
} }];
